                            h_dor_pct = d.get(f"{hk}_dor_pct");  a_dor_pct = d.get(f"{ak}_dor_pct")   # Opp ORB% THIS team allows
                            h_dft_rt  = d.get(f"{hk}_dft_rate"); a_dft_rt  = d.get(f"{ak}_dft_rate")  # FT rate THIS team allows
